-- Record the receipt each old mirror deletion was paired with.
--
-- Run on the ingest machine only. It writes `paired_hash` on 5,022 existing
-- transaction tombstones and touches nothing else. The next delta carries the
-- column to the deployment box, because every tombstone ships with every delta.
--
-- Why. Mirror collapse deletes the payer's expenditure and keeps the
-- recipient's contribution. Until 2026-10-12 it recorded no pair, so a receipt
-- used once looked free to every later sweep and rebuild, and one receipt could
-- absorb several payments. The code now records each new pair and never offers
-- a recorded receipt again. This file records the pairs made before that, so a
-- later merge or a late filing cannot pair one of those receipts a second time.
--
-- Provenance. The deleted rows are not in the database. Their content came from
-- the 2026-09-05 full dump and the 2026-08-22 deployment-box dump: 5,162 of the
-- 5,531 mirror tombstones (the other 369 were filed and deleted between dumps).
-- Each row was mapped to today's nodes through the merge tombstones. Rows the
-- campaign-account sweep had moved onto a candidate were matched by the person
-- the payee names. They were then paired with today's contributions by the
-- same one-to-one matching `collapseMirrors` uses: same payer, same amount,
-- recipient dated up to 60 days after the payer or payer up to 14 days after.
-- 5,022 found a receipt of their own. The other 140 are not written here; 16 of
-- them are restored by restore-mirror-reuse-rows.sql.
--
-- Safe to run twice: it fills only a null.
BEGIN;

UPDATE transaction_tombstones d
   SET paired_hash = v.h
  FROM (VALUES
